WITH eligible AS (SELECT s.* FROM departments s WHERE EXISTS (SELECT 1 FROM employees ch WHERE ch.dept_id = s.id AND ch.full_name LIKE '%Ford%')) SELECT id, dept_name, location, budget, CASE WHEN location RLIKE '^(New York|London)$' THEN 'GROUP_A' WHEN location RLIKE '^(Bangkok|Chiang Mai)$' THEN 'GROUP_B' ELSE 'PRIORITY' END AS location_zone FROM eligible ORDER BY location_zone DESC NULLS FIRST, id DESC LIMIT 5;
